// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/// @title Lease Contract System
/// @notice This system manages individual lease agreements and their creation through a factory contract.

/// @notice Contract for each individual unit for lease
contract LeaseContract {

    address payable parentContract;
    address public lessee;
    uint public unitNumber;
    uint public leaseTermination;
    uint public leaseAmount;

    enum Status { PENDING, PAID, TERMINATED }
    Status public status;

    /// @notice Restricts access to only the lessee of this contract
    modifier onlyLessee() {
        // TO ADD: Validate if the caller is the lessee
        require(msg.sender == lessee);
        _;
    }

    /// @notice Initializes a new lease contract for a specific unit and lessee
    constructor(address _lessee, uint _unitNumber, uint _leaseAmount) {
        // TO ADD: Initialize the lease contract with lessee, unit number, lease amount, and set status to PENDING
        lessee = _lessee;
        unitNumber = _unitNumber;
        leaseAmount = _leaseAmount;
        status = Status.PENDING;
        parentContract = payable(msg.sender);
    }

    /// @notice Allows the lessee to pay for the lease
    function payLease() public payable onlyLessee {
        // TO ADD: Ensure the lease is in PENDING status, otherwise return "Already paid"
        require(status == Status.PENDING, "Already paid");
        // TO ADD: Validate the payment amount and update status and lease termination date
        require(msg.value == leaseAmount);

        // TO ADD: Set status to PAID, update lease termination 52 weeks from current timestamp, 
        //          and transfer the lease amount to the parent contract
        status = Status.PAID;
        leaseTermination = block.timestamp + 52 weeks;
        parentContract.call{value:leaseAmount}("");
    }

    /// @notice Terminates the lease after the lease period ends
    function terminate() public {
        // TO ADD: Ensure only the parent contract can call this function
        require(msg.sender == parentContract);

        // TO ADD: Ensure the current time is past the lease termination time
        require(block.timestamp >= leaseTermination);

        // TO ADD: Update the lease status to TERMINATED
        status = Status.TERMINATED;
    }
}

/// @notice Factory contract that manages the creation and tracking of multiple leases
contract LeaseFactoryContract {

    LeaseContract[] private deployedLeases;

    address private property_manager;
    string public property_name;

    mapping(uint => bool) private unitStatus;
    mapping(uint => address) public unitContract;

    /// @notice Restricts access to only the property manager
    modifier onlyPropertyManager() {
        // TO ADD: Validate if the caller is the property manager, otherwise return "Not property manager"
        require(msg.sender == property_manager, "Not property manager");
        _;
    }

    /// @notice Initializes a new property factory
    constructor(string memory _property_name) {
        // TO ADD: Set the deployer as the property manager and initialize the property name
        property_manager = msg.sender;
        property_name = _property_name;
    }

    /// @notice Allows the contract to receive Ether payments
    // TO ADD: Allow the contract to receive Ether payments without any function call
    receive() external payable {}

    /// @notice Marks a unit as open for leasing
    function openProperty(uint _unitNumber) public onlyPropertyManager {
        // TO ADD: Ensure the unit is not already open or occupied, otherwise return "Already open or occupied"
        require(!unitStatus[_unitNumber], "Already open or occupied");
        // TO ADD: Mark the unit status as open for leasing
        unitStatus[_unitNumber] = true;
    }

    /// @notice Starts a new lease for a given unit
    function startLease(address _lessee, uint _unitNumber, uint _leaseAmount) public onlyPropertyManager {
        // TO ADD: Ensure the unit is not already occupied, otherwise return "Already occupied"
        require(unitStatus[_unitNumber], "Already occupied");

        // TO ADD: Create a new LeaseContract, update unit status and contract mappings, and store the lease in deployedLeases
        LeaseContract newLease = new LeaseContract(_lessee, _unitNumber, _leaseAmount);
        unitStatus[_unitNumber] = false;
        unitContract[_unitNumber] = address(newLease);
        deployedLeases.push(newLease);
    }

    /// @notice Terminates an active lease
    function terminateLease(address _leaseContract) public onlyPropertyManager {
        // TO ADD: Call the terminate function on the specified lease contract
        for (uint i = 0; i < deployedLeases.length; i++) {
            if (address(deployedLeases[i]) == _leaseContract) {
                deployedLeases[i].terminate();
                // TO ADD: Update the unit status to open
                unitStatus[deployedLeases[i].unitNumber()] = true;
            }
        }
    }

    /// @notice Returns the total amount of Ether held by the factory
    function getTotalPayments() public view returns (uint) {
        // TO ADD: Return the balance of the contract
        return address(this).balance;
    }

    /// @notice Retrieves the list of all deployed leases
    function getDeployedLeases() public view returns (LeaseContract[] memory) {
        // TO ADD: Return the array of deployed leases
        return deployedLeases;
    }
}

